// Differential tests against the official Claude Code You should know module.
//
// The fixture is generated by `node scripts/parity/update.mjs` from a real
// Claude Code binary.  These tests never need the binary; they compare this
// plugin's pure logic and UI trees with the recorded official outputs.

import { expect, test } from 'claude-code/testing'
import fixture from './fixtures/official.mjs'
import { makeUI, normalizeTree, normalizeValue } from '../../scripts/parity/tree.mjs'
import * as constants from '../../lib/constants.js'
import * as data from '../../lib/data.js'
import * as prompts from '../../lib/prompts.js'
import * as parse from '../../lib/parse.js'
import * as text from '../../lib/text.js'
import * as telemetry from '../../lib/telemetry.js'
import * as ui from '../../lib/ui.js'

const noop = () => {}

function normalizeKnown(value: unknown): unknown {
  if (typeof value === 'string') {
    return value
      .replaceAll('/plugin disable cc-plugin-you-should-know@builtin', '<off-command>')
      .replaceAll('/plugin disable sidelens', '<off-command>')
  }
  if (Array.isArray(value)) return value.map(normalizeKnown)
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {}
    for (const key of Object.keys(value)) out[key] = normalizeKnown((value as any)[key])
    return out
  }
  return value
}

function checkJson(label: string, actual: unknown, expected: unknown) {
  try {
    expect(normalizeValue(normalizeKnown(actual))).toEqual(normalizeValue(normalizeKnown(expected)))
  } catch (error) {
    throw new Error(`${label}: ${(error as Error).message}`)
  }
}

function checkText(label: string, actual: string, expected: string) {
  if (actual === expected) return
  let index = 0
  while (index < actual.length && index < expected.length && actual[index] === expected[index]) {
    index += 1
  }
  const context = 60
  const start = Math.max(0, index - context)
  const tail = (value: string) => JSON.stringify(value.slice(start, start + context * 2))
  throw new Error(
    `${label} differs at ${index}\nexpected: ${tail(expected)}\nactual:   ${tail(actual)}`,
  )
}

test('the fixture is a current parity fixture for this project', () => {
  expect(fixture.schemaVersion).toBe(1)
  expect(typeof fixture.claudeCodeVersion).toBe('string')
  expect(fixture.claudeCodeVersion.length).toBeGreaterThan(0)
  expect(fixture.scan.hooks).toEqual([
    'prompt.submit',
    'command.run',
    'turn.step',
    'ui.render',
    'session.detach',
    'session.end',
  ])
  expect(fixture.scan.calls).toHaveLength(18)
})


test('intentional differences stay pinned while parity normalization is active', () => {
  expect(fixture.pluginName).toBe('cc-plugin-you-should-know')
  expect(constants.PLUGIN_NAME).toBe('sidelens')
  expect(constants.OFF_COMMAND).toBe('/plugin disable sidelens')
})

test('prompts match the official bytes', () => {
  for (const testCase of fixture.prompts.propose) {
    checkText(
      `proposePrompt/${testCase.name}`,
      prompts.proposePrompt(testCase.seen, testCase.known),
      testCase.text,
    )
  }
  for (const testCase of fixture.prompts.explain) {
    checkText(
      `explainPrompt/${testCase.name}`,
      prompts.explainPrompt(testCase.topic, testCase.previous),
      testCase.text,
    )
  }
})

test('proposal parsing matches the official parser', () => {
  for (const testCase of fixture.parse.proposed) {
    checkJson(
      `parseProposedLine/${testCase.name}`,
      parse.parseProposedLine(testCase.input),
      testCase.output,
    )
  }
})

test('explanation parsing matches the official parser', () => {
  for (const testCase of fixture.parse.explanation) {
    checkJson(
      `parseExplanation/${testCase.name}`,
      parse.parseExplanation(testCase.input),
      testCase.output,
    )
  }
})

test('text measurement and truncation match the official helpers', () => {
  for (const testCase of fixture.text.cells) {
    expect(text.cellsAtMost(testCase.value), `${testCase.name}/cellsAtMost`).toBe(testCase.cellsAtMost)
    expect(text.lineCellsAtMost(testCase.value), `${testCase.name}/lineCellsAtMost`).toBe(
      testCase.lineCellsAtMost,
    )
    expect(text.noteTopic(testCase.value), `${testCase.name}/noteTopic`).toBe(testCase.noteTopic)
    expect(text.cleanForDraft(testCase.value), `${testCase.name}/cleanForDraft`).toBe(
      testCase.cleanForDraft,
    )
  }
  for (const testCase of fixture.text.wrap) {
    expect(text.wrapRows(testCase.value, testCase.columns), `${testCase.name}/wrapRows`).toBe(
      testCase.rows,
    )
  }
  for (const testCase of fixture.text.truncate) {
    expect(
      text.truncateAtWordBoundary(testCase.value, testCase.length),
      `${testCase.name}/truncateAtWordBoundary`,
    ).toBe(testCase.shorter)
    expect(text.truncateToCells(testCase.value, testCase.length), `${testCase.name}/truncateToCells`).toBe(
      testCase.cells,
    )
  }
})

test('constant values match the official module', () => {
  for (const name of Object.keys(fixture.constants)) {
    if (name === 'TERMINAL_COPY' || name === 'APP_COPY') {
      checkJson(name, ui[name], fixture.constants[name])
      continue
    }
    if (!(name in constants)) {
      throw new Error(`missing constant in lib/constants.js: ${name}`)
    }
    checkJson(name, constants[name], fixture.constants[name])
  }
})

test('telemetry records match the official builders', () => {
  for (const testCase of fixture.telemetry.answered) {
    checkJson(`answered/${testCase.name}`, telemetry.answered(testCase.record), testCase.output)
  }
  for (const testCase of fixture.telemetry.explained) {
    checkJson(`explained/${testCase.name}`, telemetry.explained(testCase.record), testCase.output)
  }
  for (const testCase of fixture.telemetry.proposed) {
    checkJson(`proposed/${testCase.name}`, telemetry.proposed(testCase.record), testCase.output)
  }
  for (const testCase of fixture.telemetry.page) {
    checkJson(`page/${testCase.name}`, telemetry.page(testCase.record), testCase.output)
  }
  for (const testCase of fixture.telemetry.version) {
    const mark = telemetry.versionMarkOf(testCase.version)
    checkJson(`versionMarkOf/${testCase.name}`, mark, testCase.mark)
    checkJson(`versionProps/${testCase.name}`, telemetry.versionProps(mark), testCase.props)
  }
})

